# Paths and options for launch_tests.ps1 and install_server.ps1 (both dot-source this file).
#
# Do not edit this file for your own machine. Put your values in autotest.settings.local.ps1 next to it
# (git-ignored), loaded right after this one, e.g. to reuse a server you already have instead of a second copy:
#
#   $Settings.ServerDir   = 'C:\games\A3\Arma3\A3Master'
#   $Settings.SteamCmdDir = 'C:\games\A3\Steam'
#   $Settings.SteamUser   = 'mysteamname'
#   $Settings.ModsFile    = 'C:\games\A3\configs\Antistasi Debug\mods.txt'
#   $Settings.WorkshopDir = 'C:\games\A3\Steam\steamapps\workshop\content\107410'
#   $Settings.SaveProfile = 'C:\games\A3\configs\Antistasi Debug\Users\AntistasiServer'
#
# A parameter given on the command line wins over both files.

# Arma 3 dedicated server install (arma3server_x64.exe). install_server.ps1 installs or updates it here.
$Settings.ServerDir = Join-Path $PSScriptRoot 'work\arma3server'

# SteamCMD folder (steamcmd.exe). install_server.ps1 downloads SteamCMD here when it is missing.
$Settings.SteamCmdDir = Join-Path $PSScriptRoot 'work\steamcmd'

# Steam account for SteamCMD. Steam refuses anonymous downloads of the Arma 3 server (app 233780,
# 'No subscription'), so an account that owns Arma 3 is needed. STEAM_USERNAME in the environment wins (CI).
$Settings.SteamUser = ''

# Mod list in the launcher format (<workshopId> <name> or <C:\path\@mod> <name> per line).
# Empty = vanilla: only @A3A and the test addon.
$Settings.ModsFile = ''

# Steam Workshop content folder for the workshop IDs in ModsFile.
$Settings.WorkshopDir = ''

# Server profile folder (Users\<name>) whose saves are copied for '@start: load' tests. Never written.
# Empty = no saves. The difficulty settings always come from Tools\AutoTest\server\A3ATest.Arma3Profile.
$Settings.SaveProfile = ''

# Game port of the test server. Steam query port is Port + 1.
$Settings.Port = 2402
